1	"use server";
2	
3	import { after } from "next/server";
4	import { revalidatePath } from "next/cache";
5	import { redirect } from "next/navigation";
6	import { createClient } from "@/lib/supabase/server";
7	import { createAdminClient } from "@/lib/supabase/admin";
8	import type { SupabaseClient } from "@supabase/supabase-js";
9	import { requireCapability, requireUser } from "@/lib/auth/dal";
10	import { PUBLIC_SITE_URL } from "@/lib/email/config";
11	import { topicSchema, replySchema, reportSchema } from "@/lib/validation/forum";
12	import { slugify } from "@/lib/forum/slug";
13	import { commitForumImages } from "@/lib/forum/images";
14	import {
15	  notifyForumReply,
16	  notifyNewReport,
17	  notifyReportResolved,
18	} from "@/lib/email/send";
19	
20	/** Plain-text, single-line preview of a markdown body for email. */
21	function excerpt(body: string, max = 180): string {
22	  const flat = body.replace(/\s+/g, " ").trim();
23	  return flat.length > max ? `${flat.slice(0, max)}…` : flat;
24	}
25	
26	export type ForumFormState = { error?: string; ok?: boolean };
27	
28	/** Create a topic, generating a unique permanent slug (retry on collision). */
29	export async function createTopic(
30	  _prev: ForumFormState,
31	  formData: FormData,
32	): Promise<ForumFormState> {
33	  const user = await requireUser();
34	
35	  const parsed = topicSchema.safeParse({
36	    title: formData.get("title"),
37	    body: formData.get("body"),
38	    category_id: formData.get("category_id"),
39	  });
40	  if (!parsed.success) {
41	    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
42	  }
43	
44	  const supabase = await createClient();
45	  const base = slugify(parsed.data.title);
46	
47	  let createdSlug: string | null = null;
48	  for (let attempt = 0; attempt < 4; attempt += 1) {
49	    const slug = `${base}-${Math.random().toString(36).slice(2, 8)}`;
50	    const { data, error } = await supabase
51	      .from("topics")
52	      .insert({
53	        slug,
54	        title: parsed.data.title,
55	        body: parsed.data.body,
56	        category_id: parsed.data.category_id,
57	        author_id: user.id,
58	      })
59	      .select("slug")
60	      .single();
61	
62	    if (!error) {
63	      createdSlug = (data as { slug: string }).slug;
64	      break;
65	    }
66	    if (error.code !== "23505") return { error: error.message };
67	  }
68	
69	  if (!createdSlug) {
70	    return { error: "Could not generate a unique URL. Please try again." };
71	  }
72	
73	  await commitForumImages(supabase, parsed.data.body);
74	
75	  revalidatePath("/discussions");
76	  redirect(`/discussions/${createdSlug}`);
77	}
78	
79	/** Post a reply to a topic (blocked if the topic is locked). */
80	export async function createReply(
81	  _prev: ForumFormState,
82	  formData: FormData,
83	): Promise<ForumFormState> {
84	  const user = await requireUser();
85	
86	  const topicId = String(formData.get("topic_id") ?? "");
87	  const slug = String(formData.get("slug") ?? "");
88	  if (!topicId) return { error: "Missing topic." };
89	
90	  const parsed = replySchema.safeParse({ body: formData.get("body") });
91	  if (!parsed.success) {
92	    return { error: parsed.error.issues[0]?.message ?? "Write a reply." };
93	  }
94	
95	  const supabase = await createClient();
96	
97	  const { data: topic } = await supabase
98	    .from("topics")
99	    .select("is_locked, author_id, title, slug")
100	    .eq("id", topicId)
101	    .maybeSingle<{
102	      is_locked: boolean;
103	      author_id: string | null;
104	      title: string;
105	      slug: string;
106	    }>();
107	  if (topic?.is_locked) {
108	    return { error: "This topic is locked." };
109	  }
110	
111	  const { error } = await supabase
112	    .from("posts")
113	    .insert({ topic_id: topicId, body: parsed.data.body, author_id: user.id });
114	  if (error) return { error: error.message };
115	
116	  await commitForumImages(supabase, parsed.data.body);
117	
118	  // Notify the topic author (not the replier themselves).
119	  if (topic && topic.author_id && topic.author_id !== user.id) {
120	    const replierName = user.displayName ?? user.username ?? "Someone";
121	    const body = parsed.data.body;
122	    after(() =>
123	      notifyForumReply({
124	        topicAuthorId: topic.author_id!,
125	        topicTitle: topic.title,
126	        slug: topic.slug,
127	        replierName,
128	        excerpt: excerpt(body),
129	      }),
130	    );
131	  }
132	
133	  if (slug) revalidatePath(`/discussions/${slug}`);
134	  return { ok: true };
135	}
136	
137	type ItemTopic = { id: string; slug: string; is_locked: boolean };
138	
139	/**
140	 * The forum topic backing a project/tool discussion, created lazily on the
141	 * first reply. Uses the secret-key client so the topic is system-owned
142	 * (author_id null) — no single user owns or can delete the shared thread. The
143	 * (item_type, item_id) unique index resolves the create race.
144	 */
145	async function ensureItemTopic(
146	  admin: SupabaseClient,
147	  itemType: "project" | "tool",
148	  itemId: string,
149	  title: string,
150	): Promise<ItemTopic> {
151	  const existing = await admin
152	    .from("topics")
153	    .select("id, slug, is_locked")
154	    .eq("item_type", itemType)
155	    .eq("item_id", itemId)
156	    .maybeSingle<ItemTopic>();
157	  if (existing.data) return existing.data;
158	
159	  const base = slugify(title) || itemType;
160	  const slug = `${base}-${Math.random().toString(36).slice(2, 8)}`;
161	  const path = itemType === "project" ? "/projects" : "/tools";
162	  const { data, error } = await admin
163	    .from("topics")
164	    .insert({
165	      slug,
166	      title: title.slice(0, 140),
167	      body: `Discussion for the ${itemType} [${title}](${PUBLIC_SITE_URL}${path}/${itemId}).`,
168	      item_type: itemType,
169	      item_id: itemId,
170	      author_id: null,
171	      category_id: null,
172	    })
173	    .select("id, slug, is_locked")
174	    .single<ItemTopic>();
175	  if (!error && data) return data;
176	
177	  // Lost the create race — the other writer's topic now exists.
178	  const again = await admin
179	    .from("topics")
180	    .select("id, slug, is_locked")
181	    .eq("item_type", itemType)
182	    .eq("item_id", itemId)
183	    .maybeSingle<ItemTopic>();
184	  if (again.data) return again.data;
185	  throw new Error(error?.message ?? "Could not start the discussion.");
186	}
187	
188	/** Post a reply to a project/tool discussion, starting the thread if needed. */
189	export async function createItemReply(
190	  _prev: ForumFormState,
191	  formData: FormData,
192	): Promise<ForumFormState> {
193	  const user = await requireUser();
194	
195	  const itemType = String(formData.get("item_type") ?? "");
196	  const itemId = String(formData.get("item_id") ?? "");
197	  const itemTitle = String(formData.get("item_title") ?? "").trim();
198	  const itemPath = String(formData.get("item_path") ?? "");
199	  if (itemType !== "project" && itemType !== "tool") {
200	    return { error: "Unknown item." };
201	  }
202	  if (!itemId) return { error: "Missing item." };
203	
204	  const parsed = replySchema.safeParse({ body: formData.get("body") });
205	  if (!parsed.success) {
206	    return { error: parsed.error.issues[0]?.message ?? "Write a reply." };
207	  }
208	
209	  const admin = createAdminClient();
210	  const topic = await ensureItemTopic(
211	    admin,
212	    itemType,
213	    itemId,
214	    itemTitle || itemType,
215	  );
216	  if (topic.is_locked) return { error: "This discussion is locked." };
217	
218	  const supabase = await createClient();
219	  const { error } = await supabase
220	    .from("posts")
221	    .insert({ topic_id: topic.id, body: parsed.data.body, author_id: user.id });
222	  if (error) return { error: error.message };
223	
224	  await commitForumImages(supabase, parsed.data.body);
225	
226	  if (itemPath.startsWith("/")) revalidatePath(itemPath);
227	  return { ok: true };
228	}
229	
230	/** Delete a topic. RLS restricts to the author or an admin. */
231	export async function deleteTopic(formData: FormData): Promise<void> {
232	  await requireUser();
233	  const id = String(formData.get("id") ?? "");
234	  if (!id) return;
235	
236	  const supabase = await createClient();
237	  const { error } = await supabase.from("topics").delete().eq("id", id);
238	  if (error) throw error;
239	
240	  revalidatePath("/discussions");
241	  redirect("/discussions");
242	}
243	
244	/** Delete a reply. RLS restricts to the author or an admin. */
245	export async function deletePost(formData: FormData): Promise<void> {
246	  await requireUser();
247	  const id = String(formData.get("id") ?? "");
248	  const slug = String(formData.get("slug") ?? "");
249	  if (!id) return;
250	
251	  const supabase = await createClient();
252	  const { error } = await supabase.from("posts").delete().eq("id", id);
253	  if (error) throw error;
254	
255	  if (slug) revalidatePath(`/discussions/${slug}`);
256	}
257	
258	/** Lock/unlock a topic (admin/moderator only). */
259	export async function setTopicLock(formData: FormData): Promise<void> {
260	  await requireCapability("moderate");
261	  const id = String(formData.get("id") ?? "");
262	  const slug = String(formData.get("slug") ?? "");
263	  const locked = formData.get("locked") === "true";
264	  if (!id) return;
265	
266	  const supabase = await createClient();
267	  const { error } = await supabase
268	    .from("topics")
269	    .update({ is_locked: locked })
270	    .eq("id", id);
271	  if (error) throw error;
272	
273	  if (slug) revalidatePath(`/discussions/${slug}`);
274	}
275	
276	/** Pin/unpin a topic (admin/moderator only). */
277	export async function setTopicPin(formData: FormData): Promise<void> {
278	  await requireCapability("moderate");
279	  const id = String(formData.get("id") ?? "");
280	  const slug = String(formData.get("slug") ?? "");
281	  const pinned = formData.get("pinned") === "true";
282	  if (!id) return;
283	
284	  const supabase = await createClient();
285	  const { error } = await supabase
286	    .from("topics")
287	    .update({ is_pinned: pinned })
288	    .eq("id", id);
289	  if (error) throw error;
290	
291	  if (slug) revalidatePath(`/discussions/${slug}`);
292	}
293	
294	/** File a moderation report against a topic or post. */
295	export async function reportContent(
296	  _prev: ForumFormState,
297	  formData: FormData,
298	): Promise<ForumFormState> {
299	  const user = await requireUser();
300	
301	  const parsed = reportSchema.safeParse({
302	    target_type: formData.get("target_type"),
303	    target_id: formData.get("target_id"),
304	    reason: formData.get("reason"),
305	  });
306	  if (!parsed.success) return { error: "Could not file that report." };
307	
308	  const supabase = await createClient();
309	  const reason =
310	    parsed.data.reason && parsed.data.reason !== "" ? parsed.data.reason : null;
311	  const { error } = await supabase.from("reports").insert({
312	    reporter_id: user.id,
313	    target_type: parsed.data.target_type,
314	    target_id: parsed.data.target_id,
315	    reason,
316	  });
317	  if (error) return { error: error.message };
318	
319	  after(() =>
320	    notifyNewReport({
321	      targetType: parsed.data.target_type,
322	      reason: reason ?? "",
323	    }),
324	  );
325	
326	  return { ok: true };
327	}
328	
329	/** Resolve or dismiss a report (admin/moderator only). */
330	export async function resolveReport(formData: FormData): Promise<void> {
331	  const admin = await requireCapability("moderate");
332	  const id = String(formData.get("id") ?? "");
333	  const status = formData.get("status") === "dismissed" ? "dismissed" : "resolved";
334	  if (!id) return;
335	
336	  const supabase = await createClient();
337	
338	  // Capture the reporter before updating so we can close the loop by email.
339	  const { data: report } = await supabase
340	    .from("reports")
341	    .select("reporter_id, target_type")
342	    .eq("id", id)
343	    .maybeSingle<{ reporter_id: string | null; target_type: string }>();
344	
345	  const { error } = await supabase
346	    .from("reports")
347	    .update({
348	      status,
349	      resolved_by: admin.id,
350	      resolved_at: new Date().toISOString(),
351	    })
352	    .eq("id", id);
353	  if (error) throw error;
354	
355	  if (report?.reporter_id) {
356	    const reporterId = report.reporter_id;
357	    const contextLabel = `a ${report.target_type}`;
358	    after(() =>
359	      notifyReportResolved({ reporterId, status, contextLabel }),
360	    );
361	  }
362	
363	  revalidatePath("/admin/reports");
364	}
365

