1	import { createAdminClient } from "@/lib/supabase/admin";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { FORUM_IMAGE_BUCKET } from "@/lib/forum/image-constants";
4	import { collectReferencedForumImagePaths } from "@/lib/forum/images";
5	
6	/**
7	 * Reclaim forum image uploads that no live post references. Two orphan classes:
8	 *
9	 *  1. Abandoned — uploaded from a composer whose post was never submitted, so
10	 *     the ledger row stayed `committed = false`. Reclaimed after a grace window
11	 *     (an upload can sit in a draft for a while).
12	 *  2. Dangling — once referenced, but the topic/reply was later deleted (or
13	 *     edited to drop the image), so the path no longer appears in any body.
14	 *
15	 * Invoked by Vercel Cron (see vercel.json). Vercel sends the CRON_SECRET as a
16	 * bearer token; we reject anything else so the endpoint can't be triggered by
17	 * the public.
18	 */
19	const GRACE_HOURS = 24;
20	const BATCH = 500;
21	
22	type Row = { id: string; path: string };
23	
24	/** Delete the storage objects + ledger rows for a set of uploads. */
25	async function reclaim(
26	  supabase: SupabaseClient,
27	  rows: Row[],
28	): Promise<{ error?: string }> {
29	  if (rows.length === 0) return {};
30	  const { error: removeError } = await supabase.storage
31	    .from(FORUM_IMAGE_BUCKET)
32	    .remove(rows.map((r) => r.path));
33	  if (removeError) return { error: removeError.message };
34	
35	  const { error: deleteError } = await supabase
36	    .from("forum_uploads")
37	    .delete()
38	    .in("id", rows.map((r) => r.id));
39	  if (deleteError) return { error: deleteError.message };
40	  return {};
41	}
42	
43	export async function GET(request: Request) {
44	  const secret = process.env.CRON_SECRET;
45	  if (secret) {
46	    const auth = request.headers.get("authorization");
47	    if (auth !== `Bearer ${secret}`) {
48	      return Response.json({ error: "unauthorized" }, { status: 401 });
49	    }
50	  }
51	
52	  const supabase = createAdminClient();
53	  const cutoff = new Date(Date.now() - GRACE_HOURS * 60 * 60 * 1000).toISOString();
54	
55	  // Phase 1 — abandoned uploads (never committed, past the grace window).
56	  const { data: stale, error: staleError } = await supabase
57	    .from("forum_uploads")
58	    .select("id, path")
59	    .eq("committed", false)
60	    .lt("created_at", cutoff)
61	    .limit(BATCH);
62	  if (staleError) {
63	    return Response.json({ error: staleError.message }, { status: 500 });
64	  }
65	  const abandoned = (stale ?? []) as Row[];
66	  const r1 = await reclaim(supabase, abandoned);
67	  if (r1.error) return Response.json({ error: r1.error }, { status: 500 });
68	
69	  // Phase 2 — dangling uploads (committed, but no live body still references
70	  // the path). The grace window also shields a just-committed image from a race
71	  // with its own post insert. Correctness guard: collectReferenced* paginates
72	  // every image-bearing body, so a live image is never mistaken for an orphan.
73	  const referenced = await collectReferencedForumImagePaths(supabase);
74	  const { data: live, error: liveError } = await supabase
75	    .from("forum_uploads")
76	    .select("id, path")
77	    .eq("committed", true)
78	    .lt("created_at", cutoff)
79	    .limit(BATCH);
80	  if (liveError) {
81	    return Response.json({ error: liveError.message }, { status: 500 });
82	  }
83	  const dangling = ((live ?? []) as Row[]).filter(
84	    (r) => !referenced.has(r.path),
85	  );
86	  const r2 = await reclaim(supabase, dangling);
87	  if (r2.error) return Response.json({ error: r2.error }, { status: 500 });
88	
89	  return Response.json({
90	    abandoned: abandoned.length,
91	    dangling: dangling.length,
92	  });
93	}
