// 3. YouTube oEmbed
await test("YouTube oEmbed",async()=>{
  const u="https://www.youtube.com/watch?v=dQw4w9WgXcQ";
  const r=await safeFetch(`https://www.youtube.com/oembed?format=json&url=${encodeURIComponent(u)}`,{accept:["application/json","text/javascript"]});
  const d=JSON.parse(new TextDecoder().decode(r.body));
  console.log("   title:",d.title,"| author:",d.author_name,"| thumb:",(d.thumbnail_url||"").slice(0,50));
  if(!d.thumbnail_url)throw new Error("no thumbnail");
});
// 4. SSRF: cloud metadata IP must be blocked
await test("SSRF block 169.254.169.254",async()=>{
