          <ul className="mt-4 flex flex-col gap-4">
            {posts.map((post) => {
              const canDelete = Boolean(
                user && (user.id === post.author_id || isAdmin),
              );
              return (
                <li
                  key={post.id}
                  className="rounded-[var(--radius-comic)] border-ink bg-surface p-5 shadow-comic"
                >
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2 text-sm text-brand-ink/60">
                      <AuthorChip author={post.author} />
                      <span>· {timeAgo(post.created_at)}</span>
                    </div>
                  </div>
                  <div className="mt-3">
                    <Markdown>{post.body}</Markdown>
                    <LinkPreviews body={post.body} previews={previews} />
                  </div>
                  <div className="mt-3 flex items-center gap-3">
                    {canDelete && (
                      <form action={deletePost}>
                        <input type="hidden" name="id" value={post.id} />
                        <input type="hidden" name="slug" value={topic.slug} />
                        <button
                          type="submit"
                          className="focus-comic font-mono text-xs uppercase tracking-widest text-muted hover:text-brand-purple"
                        >
                          Delete
                        </button>
                      </form>
                    )}
                    {user && (
                      <ReportButton targetType="post" targetId={post.id} />
                    )}
                  </div>
                </li>
              );
            })}
          </ul>

          {/* Reply box */}
          <div className="mt-8">
            {topic.is_locked ? (
              <p className="rounded-[var(--radius-comic)] border-ink bg-surface p-4 font-display uppercase tracking-wide text-brand-ink/60 shadow-comic">
                This topic is locked.
              </p>
            ) : user ? (
              <ReplyForm topicId={topic.id} slug={topic.slug} />
            ) : (
              <div className="flex flex-col gap-2">
                <ComicButton
                  href={`/login?next=${encodeURIComponent(`/discussions/${topic.slug}`)}`}
                  variant="blue"
                >
                  Sign in to reply
                </ComicButton>
                <p className="font-mono text-xs uppercase tracking-widest text-muted">
                  Free · Sign in with GitHub to join the conversation
                </p>
              </div>
            )}
          </div>
        </section>
      </main>
      <SiteFooter />
    </>
  );
}

import { Markdown } from "@/components/markdown/markdown";
import { AuthorChip } from "@/components/forum/author-chip";
import { ReportButton } from "@/components/forum/report-button";
import { ItemReplyForm } from "@/components/forum/item-reply-form";
import { ComicButton } from "@/components/brand/comic-button";
import { getSessionUser } from "@/lib/auth/dal";
import { getItemTopic, listPosts } from "@/lib/forum/queries";
import { getLinkPreviewsForBodies } from "@/lib/links/queries";
import { LinkPreviews } from "@/components/links/link-preview-card";
import { deletePost } from "@/lib/forum/actions";
import { timeAgo } from "@/lib/forum/format";

/**
 * On-site discussion for a project or tool, backed by the forum. The topic is
 * created lazily on the first reply, so until then this is just an invitation
 * to start the conversation.
 */
export async function ItemDiscussion({
  itemType,
  itemId,
  itemTitle,
  itemPath,
}: {
  itemType: "project" | "tool";
  itemId: string;
  itemTitle: string;
  itemPath: string;
}) {
  const [user, topic] = await Promise.all([
    getSessionUser(),
    getItemTopic(itemType, itemId),
  ]);
  const posts = topic ? await listPosts(topic.id) : [];
  const isAdmin = user?.role === "admin" || user?.role === "moderator";
  const previews = await getLinkPreviewsForBodies(posts.map((p) => p.body));

  return (
    <section id="discussion" className="mt-10 scroll-mt-24">
      <h2 className="font-display text-2xl uppercase tracking-wide text-brand-ink">
        Discussion{posts.length > 0 ? ` (${posts.length})` : ""}
      </h2>

      {posts.length > 0 && (
        <ul className="mt-4 flex flex-col gap-4">
          {posts.map((post) => {
            const canDelete = Boolean(
              user && (user.id === post.author_id || isAdmin),
            );
            return (
              <li
                key={post.id}
                className="rounded-[var(--radius-comic)] border-ink bg-surface p-5 shadow-comic"
              >
                <div className="flex items-center gap-2 text-sm text-brand-ink/60">
                  <AuthorChip author={post.author} />
                  <span>· {timeAgo(post.created_at)}</span>
                </div>
                <div className="mt-3">
                  <Markdown>{post.body}</Markdown>
                  <LinkPreviews body={post.body} previews={previews} />
                </div>
                <div className="mt-3 flex items-center gap-3">
                  {canDelete && topic && (
                    <form action={deletePost}>
                      <input type="hidden" name="id" value={post.id} />
                      <input type="hidden" name="slug" value={topic.slug} />
                      <button
                        type="submit"
                        className="focus-comic font-mono text-xs uppercase tracking-widest text-muted hover:text-brand-purple"
                      >
                        Delete
                      </button>
                    </form>
                  )}
                  {user && <ReportButton targetType="post" targetId={post.id} />}
                </div>
              </li>
            );
          })}
        </ul>
      )}

      <div className="mt-8">
        {topic?.is_locked ? (
          <p className="rounded-[var(--radius-comic)] border-ink bg-surface p-4 font-display uppercase tracking-wide text-brand-ink/60 shadow-comic">
            This discussion is locked.
          </p>
        ) : user ? (
          <ItemReplyForm
            itemType={itemType}
            itemId={itemId}
            itemTitle={itemTitle}
            itemPath={itemPath}
          />
        ) : (
          <div className="flex flex-col gap-2">
            <ComicButton
              href={`/login?next=${encodeURIComponent(itemPath)}`}
              variant="blue"
            >
              Sign in to discuss
            </ComicButton>
            <p className="font-mono text-xs uppercase tracking-widest text-muted">
              Free · Sign in with GitHub to join the conversation
            </p>
          </div>
        )}
      </div>
    </section>
  );
}

import Link from "next/link";
import { AuthorChip } from "@/components/forum/author-chip";
import { LinkPreviews } from "@/components/links/link-preview-card";
import type { TopicListItem } from "@/lib/forum/queries";
import type { LinkPreview } from "@/lib/links/constants";
import { timeAgo, plainExcerpt } from "@/lib/forum/format";

/**
 * One topic as a social-timeline card: author up top, then the title + excerpt
 * as a single big click target into the thread, an inline link preview, and a
 * reply-count action bar. The preview card links OUT to its source; everything
 * else leads into the discussion.
 */
export function TopicCard({
  topic,
  previews,
}: {
  topic: TopicListItem;
  previews: Map<string, LinkPreview>;
}) {
  const excerpt = plainExcerpt(topic.body);
  const href = `/discussions/${topic.slug}`;

  return (
    <article className="rounded-[var(--radius-comic)] border-ink bg-surface p-5 shadow-comic transition hover:shadow-comic-lg">
      <div className="flex flex-wrap items-center gap-2 text-sm text-brand-ink/60">
        <AuthorChip author={topic.author} />
        <span>· {timeAgo(topic.last_activity_at)}</span>
        <div className="ml-auto flex flex-wrap items-center gap-2">
          {topic.is_pinned && (
            <span className="rounded-md border-[2px] border-brand-ink bg-brand-lime px-2 py-0.5 font-display text-xs uppercase text-brand-ink">
              Pinned
            </span>
          )}
          {topic.is_locked && (
            <span className="rounded-md border-[2px] border-brand-ink bg-brand-ink px-2 py-0.5 font-display text-xs uppercase text-white">
              Locked
            </span>
          )}
          {topic.category && (
            <Link
              href={`/discussions?category=${topic.category.slug}`}
              className="focus-comic font-mono text-xs uppercase tracking-widest text-muted hover:text-brand-blue"
            >
              {topic.category.name}
            </Link>
          )}
        </div>
      </div>

      <Link href={href} className="focus-comic group mt-3 block">
        <h2 className="font-display text-xl uppercase leading-tight tracking-wide text-brand-ink group-hover:text-brand-blue">
          {topic.title}
        </h2>
        {excerpt && (
          <p className="mt-1 line-clamp-3 text-brand-ink/70">{excerpt}</p>
        )}
      </Link>

      <LinkPreviews body={topic.body} previews={previews} limit={1} />

      <div className="mt-4 flex items-center gap-2 border-t-[2px] border-brand-ink/10 pt-3">
        <Link
          href={href}
          className="focus-comic inline-flex items-center gap-1.5 font-mono text-xs uppercase tracking-widest text-muted hover:text-brand-purple"
        >
          <svg viewBox="0 0 24 24" aria-hidden="true" className="h-4 w-4 fill-current">
            <path d="M4 4h16a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H9l-5 4V5a1 1 0 0 1 1-1z" />
          </svg>
          {topic.reply_count} {topic.reply_count === 1 ? "reply" : "replies"}
        </Link>
      </div>
    </article>
  );
}

