import type { Metadata } from "next";
import Link from "next/link";
import { requireAdmin, userCan } from "@/lib/auth/dal";
import type { Capability } from "@/lib/auth/capabilities";

export const metadata: Metadata = { title: "Admin" };

const SECTIONS: {
  href: string;
  title: string;
  body: string;
  accent: string;
  cap: Capability;
}[] = [
  {
    href: "/admin/users",
    title: "Users",
    body: "Assign admins and grant granular capabilities. Ban members.",
    accent: "bg-brand-ink text-white",
    cap: "manage_users",
  },
  {
    href: "/admin/events",
    title: "Events",
    body: "Create and manage livestreamed meetups. Only published events are public.",
    accent: "bg-brand-blue text-white",
    cap: "manage_events",
  },
  {
    href: "/admin/reports",
    title: "Reports",
    body: "Review flagged topics and replies. Resolve or dismiss moderation reports.",
    accent: "bg-brand-purple text-white",
    cap: "moderate",
  },
  {
    href: "/admin/feedback",
    title: "Feedback",
    body: "Read and triage feedback sent from the site's feedback widget.",
    accent: "bg-brand-cream text-brand-ink",
    cap: "manage_feedback",
  },
  {
    href: "/admin/news",
    title: "Captured news",
    body: "Browse the raw Reddit/dev-news feed captured via IFTTT.",
    accent: "bg-brand-ink text-white",
    cap: "manage_social",
  },
  {
    href: "/admin/survey",
    title: "Survey results",
    body: "Who's signing up: personas, tools, AI observability, and goals.",
    accent: "bg-brand-purple text-white",
    cap: "view_insights",
  },
  {
    href: "/admin/tweets",
    title: "Tweets",
    body: "Review @devsassembleAI drafts, edit, and cross-post to X + Bluesky.",
    accent: "bg-brand-lime text-brand-ink",
    cap: "manage_social",
  },
  {
    href: "/admin/handles",
    title: "Handle registry",
    body: "Verify social handles the drafter can @-mention for reach.",
    accent: "bg-brand-blue text-white",
    cap: "manage_social",
  },
];

export default async function AdminPage() {
  const user = await requireAdmin();
  const sections = SECTIONS.filter((s) => userCan(user, s.cap));

  return (
    <main className="mx-auto max-w-4xl px-6 py-12">
      <h1 className="font-display text-5xl uppercase tracking-wide text-brand-ink">
        Admin
      </h1>
      <p className="mt-2 text-brand-ink/70">Moderator & admin tools.</p>

      <div className="mt-8 grid gap-4 sm:grid-cols-2">
        {sections.map((s) => (
          <Link
            key={s.href}
            href={s.href}
            className={`rounded-[var(--radius-comic)] border-ink p-6 shadow-comic transition-transform hover:-translate-y-0.5 hover:shadow-comic-lg ${s.accent}`}
          >
            <h2 className="font-display text-2xl uppercase tracking-wide">
              {s.title}
            </h2>
            <p className="mt-1 text-sm opacity-90">{s.body}</p>
          </Link>
        ))}
      </div>
    </main>
  );
}

import Image from "next/image";
import { extractBareUrls } from "@/lib/links/extract";
import type { LinkPreview } from "@/lib/links/constants";

function hostOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

/** A single unfurled link rendered as a comic-styled card linking out. */
export function LinkPreviewCard({
  preview,
  sourceTopicId,
  track = true,
}: {
  preview: LinkPreview;
  /** The discussion this card appears in, for click attribution. */
  sourceTopicId?: string;
  /** When false, link straight to the source (no click tracking). */
  track?: boolean;
}) {
  const source = preview.site_name ?? hostOf(preview.url);
  // Tracked clicks route through /l/[id], which logs then 302s to the source.
  const href = track
    ? `/l/${preview.id}${sourceTopicId ? `?from=${sourceTopicId}` : ""}`
    : preview.url;
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer nofollow"
      className="focus-comic group block overflow-hidden rounded-[var(--radius-comic)] border-ink bg-surface shadow-comic transition hover:shadow-comic-lg"
    >
      {preview.image_url && (
        <div className="relative aspect-[1.91/1] overflow-hidden border-b-[3px] border-brand-ink bg-brand-ink/5">
          <Image
            src={preview.image_url}
            alt=""
            fill
            sizes="(max-width: 768px) 100vw, 768px"
            className="object-cover transition group-hover:scale-[1.02]"
          />
          {preview.kind === "video" && (
            <span className="absolute inset-0 flex items-center justify-center">
              <span className="flex h-14 w-14 items-center justify-center rounded-full border-[3px] border-brand-ink bg-brand-lime shadow-comic-sm">
                <svg
                  viewBox="0 0 24 24"
                  aria-hidden="true"
                  className="ml-1 h-6 w-6 fill-brand-ink"
                >
                  <path d="M8 5v14l11-7z" />
                </svg>
              </span>
            </span>
          )}
        </div>
      )}
      <div className="p-4">
        <div className="font-mono text-xs uppercase tracking-widest text-muted">
          {source}
        </div>
        <div className="mt-1 line-clamp-2 font-display text-lg leading-tight text-brand-ink group-hover:text-brand-blue">
          {preview.title ?? preview.url}
        </div>
        {preview.description && (
          <p className="mt-1 line-clamp-2 text-sm text-brand-ink/70">
            {preview.description}
          </p>
        )}
        {preview.author && (
          <div className="mt-2 font-mono text-xs uppercase tracking-widest text-muted">
            {preview.author}
          </div>
        )}
      </div>
    </a>
  );
}

/**
 * Render preview cards for the bare URLs in `body` that have a resolved entry in
 * `previews`. URLs still pending/errored just stay as the plain markdown link
 * rendered elsewhere, so nothing shows here for them.
 */
export function LinkPreviews({
  body,
  previews,
  limit,
  sourceTopicId,
  track = true,
}: {
  body: string;
  previews: Map<string, LinkPreview>;
  /** Cap how many cards render (e.g. 1 in a timeline list). */
  limit?: number;
  /** The discussion these cards appear in, for click attribution. */
  sourceTopicId?: string;
  /** When false, cards link straight to the source (no click tracking). */
  track?: boolean;
}) {
  let cards = extractBareUrls(body)
    .map((url) => previews.get(url))
    .filter((p): p is LinkPreview => Boolean(p));
  if (limit !== undefined) cards = cards.slice(0, limit);
  if (cards.length === 0) return null;
  return (
    <div className="mt-4 flex flex-col gap-3">
      {cards.map((preview) => (
        <LinkPreviewCard
          key={preview.url}
          preview={preview}
          sourceTopicId={sourceTopicId}
          track={track}
        />
      ))}
    </div>
  );
}

